(function(){var D=(window.TIFA_DATA=window.TIFA_DATA||{});D.toxicite=D.toxicite||{};Object.assign(D.toxicite,{
 "tomate": {"niveau":"moderee","resume":"Le fruit rouge bien mûr se mange. Les feuilles, les tiges et les tomates vertes sont toxiques pour les chats, les chiens et les personnes.","animaux":{"chats":"oui","chiens":"oui","autres":"Chevaux : toxique (ASPCA)."},"humains":{"enfants":"oui","adultes":"oui","texte":"On ne mange pas les feuilles ni les tiges. Les tomates encore vertes sont à éviter en grande quantité. Les tomates mûres sont sans danger."},"parties":["Feuilles","Tiges","Fruits verts (pas mûrs)","Fleurs"],"substances":["Solanine et tomatine : des substances amères que la plante fabrique pour se défendre. Elles irritent le ventre et peuvent gêner le cœur."],"pourquoi":"La tomate fait partie de la famille des morelles. Ses feuilles et ses fruits verts contiennent des substances qui dissuadent les animaux et les insectes de les manger. Quand le fruit mûrit, ces substances baissent beaucoup. Si on mange beaucoup de feuilles ou de fruits verts, elles irritent l'estomac et peuvent ralentir le cœur.","symptomes":["Beaucoup de bave, perte d'appétit","Vomissements, diarrhée, mal au ventre","Fatigue, faiblesse","Pupilles dilatées","Cœur qui bat lentement"],"que_faire":["Ne faites pas vomir votre animal, sauf si un vétérinaire vous le demande.","Appelez tout de suite votre vétérinaire ou un service d'urgence vétérinaire. Dites quelle plante, quelle partie et quelle quantité.","Emportez un morceau de la plante ou une photo.","Si l'animal est très mou, tremble, ne respire pas bien ou perd connaissance : allez en urgence chez le vétérinaire."],"precision":"L'ASPCA cite la solanine, Pet Poison Helpline parle d'alcaloïdes (tomatine). Les quantités qui rendent malade ne sont pas précises : par prudence, on évite tout.","verifie":true,"sources":[{"titre":"ASPCA — Tomato Plant","url":"https://www.aspca.org/pet-care/aspca-poison-control/toxic-and-non-toxic-plants/tomato-plant"},{"titre":"Pet Poison Helpline — Tomato","url":"https://www.petpoisonhelpline.com/poison/tomato/"},{"titre":"ASPCA — Pets and Produce (potager)","url":"https://www.aspca.org/news/pets-and-produce-top-tips-vegetable-garden-safety"},{"titre":"La Revue du Praticien — Intoxication à la solanine","url":"https://www.larevuedupraticien.fr/article/intoxication-la-solanine"}],"precautions":["Gardez les pieds de tomate hors de portée des chats et des chiens, ou entourez-les d'un grillage.","Ne laissez pas les enfants croquer les feuilles ou les tomates vertes.","Ramassez les tomates vertes tombées au sol et les feuilles taillées.","Lavez-vous les mains après avoir enlevé les gourmands (la sève peut irriter la peau)."]},
 "tomate-cerise": {"niveau":"moderee","resume":"Les petits fruits rouges bien mûrs se mangent. Les feuilles, les tiges et les fruits verts sont toxiques pour les chats, les chiens et les personnes.","animaux":{"chats":"oui","chiens":"oui","autres":"Chevaux : toxique (ASPCA)."},"humains":{"enfants":"oui","adultes":"oui","texte":"On ne mange pas les feuilles ni les tiges. Les tomates encore vertes sont à éviter en grande quantité. Les tomates mûres sont sans danger."},"parties":["Feuilles","Tiges","Fruits verts (pas mûrs)","Fleurs"],"substances":["Solanine et tomatine : des substances amères que la plante fabrique pour se défendre. Elles irritent le ventre et peuvent gêner le cœur."],"pourquoi":"La tomate fait partie de la famille des morelles. Ses feuilles et ses fruits verts contiennent des substances qui dissuadent les animaux et les insectes de les manger. Quand le fruit mûrit, ces substances baissent beaucoup. Si on mange beaucoup de feuilles ou de fruits verts, elles irritent l'estomac et peuvent ralentir le cœur.","symptomes":["Beaucoup de bave, perte d'appétit","Vomissements, diarrhée, mal au ventre","Fatigue, faiblesse","Pupilles dilatées","Cœur qui bat lentement"],"que_faire":["Ne faites pas vomir votre animal, sauf si un vétérinaire vous le demande.","Appelez tout de suite votre vétérinaire ou un service d'urgence vétérinaire. Dites quelle plante, quelle partie et quelle quantité.","Emportez un morceau de la plante ou une photo.","Si l'animal est très mou, tremble, ne respire pas bien ou perd connaissance : allez en urgence chez le vétérinaire."],"precision":"L'ASPCA cite la solanine, Pet Poison Helpline parle d'alcaloïdes (tomatine). Les quantités qui rendent malade ne sont pas précises : par prudence, on évite tout.","verifie":true,"sources":[{"titre":"ASPCA — Tomato Plant","url":"https://www.aspca.org/pet-care/aspca-poison-control/toxic-and-non-toxic-plants/tomato-plant"},{"titre":"Pet Poison Helpline — Tomato","url":"https://www.petpoisonhelpline.com/poison/tomato/"},{"titre":"ASPCA — Pets and Produce (potager)","url":"https://www.aspca.org/news/pets-and-produce-top-tips-vegetable-garden-safety"},{"titre":"La Revue du Praticien — Intoxication à la solanine","url":"https://www.larevuedupraticien.fr/article/intoxication-la-solanine"}],"precautions":["Gardez les pieds de tomate hors de portée des chats et des chiens, ou entourez-les d'un grillage.","Ne laissez pas les enfants croquer les feuilles ou les tomates vertes.","Ramassez les tomates vertes tombées au sol et les feuilles taillées.","Lavez-vous les mains après avoir enlevé les gourmands (la sève peut irriter la peau)."]},
 "courgette": {"niveau":"moderee","resume":"La courgette normale est sans danger pour les animaux. Danger rare pour les personnes : une courgette AMÈRE ne doit jamais être mangée, même cuite.","animaux":{"chats":"non","chiens":"non","autres":"Chevaux : non toxique (ASPCA)."},"humains":{"enfants":"oui","adultes":"oui","texte":"Goûtez un petit morceau cru. Si c'est amer, crachez et jetez toute la courgette. Une courgette amère peut rendre très malade, même cuite."},"parties":["Fruit au goût amer (rare)"],"substances":["Cucurbitacines : des substances très amères et très irritantes pour le ventre. La cuisson ne les détruit pas."],"pourquoi":"Les courges sauvages et décoratives fabriquent des cucurbitacines pour ne pas être mangées. Les courgettes du jardin n'en ont presque plus, mais si on ressème des graines récoltées, une courgette peut croiser une plante amère et redevenir toxique, sans que cela se voie.","symptomes":["Goût très amer dans la bouche","Nausées, vomissements","Mal au ventre, diarrhée (parfois avec du sang)","Perte d'eau importante (déshydratation) dans les cas graves"],"que_faire":["Recrachez et rincez la bouche. Ne mangez pas le reste.","Si vous avez mangé de la courgette amère : appelez un centre antipoison ou votre médecin (exemple : centre d'Angers, 02 41 35 33 30). Gardez le reste du repas et prenez une photo.","Si les vomissements ou la diarrhée sont forts, ou si la personne est très faible : 15 ou 112."],"precision":"L'ASPCA classe la plante comme non toxique pour les animaux. Le risque de l'amertume est surtout décrit pour les personnes (ANSES, parle des courges en général).","verifie":true,"sources":[{"titre":"ASPCA — Zucchini Squash","url":"https://www.aspca.org/pet-care/aspca-poison-control/toxic-and-non-toxic-plants/zucchini-squash"},{"titre":"ANSES — Attention aux courges amères","url":"https://www.anses.fr/fr/content/attention-aux-courges-ameres"}],"precautions":["Goûtez toujours un petit bout cru avant de cuisiner.","Rachetez des graines chaque année : ne ressemez pas celles de votre potager.","Arrachez les courges qui poussent toutes seules sans que vous les ayez semées.","Ne mangez jamais les courges décoratives (coloquintes)."]},
 "laitue": {"niveau":"faible","resume":"La salade est sans danger connu pour les chiens et les personnes en petite quantité. Pour les chats, la confirmation manque : mieux vaut ne pas la laisser manger.","animaux":{"chats":"inconnu","chiens":"non","autres":""},"humains":{"enfants":"non","adultes":"non","texte":"La laitue se mange sans danger. Lavez-la bien avant de la manger."},"parties":["Aucune partie connue comme toxique"],"substances":["Aucune substance dangereuse connue."],"pourquoi":"La laitue n'est pas connue pour fabriquer des poisons. Trop de salade peut seulement donner des gaz ou la diarrhée à un animal.","symptomes":["Gaz, ventre gonflé","Diarrhée si l'animal en mange beaucoup"],"que_faire":["Rien d'urgent en général.","Si votre animal vomit beaucoup ou semble mal : appelez votre vétérinaire."],"precision":"Pas de fiche ASPCA trouvée pour la laitue. Un blog de conseils pour chiens (Rover) cite un toxicologue vétérinaire : la laitue est sans danger pour les chiens. Rien de confirmé pour les chats : par prudence, ne pas la laisser manger.","verifie":false,"sources":[{"titre":"Rover — Can my dog eat lettuce","url":"https://www.rover.com/blog/can-my-dog-eat-lettuce"}],"precautions":["Gardez les plantes hors de portée des jeunes enfants et des animaux.","Apprenez aux enfants à ne rien manger au jardin sans demander à un adulte.","Lavez-vous les mains après avoir jardiné."]},
 "radis": {"niveau":"faible","resume":"La racine se mange. Les feuilles peuvent donner mal au ventre aux chiens. Pour les chats, la confirmation manque.","animaux":{"chats":"inconnu","chiens":"non","autres":""},"humains":{"enfants":"non","adultes":"non","texte":"Le radis se mange sans danger. Il pique un peu la bouche, c'est normal."},"parties":["Feuilles (peuvent irriter le ventre des chiens)"],"substances":["Composés piquants qui irritent l'estomac en grande quantité."],"pourquoi":"Le radis fait partie des crucifères. Il fabrique des composés piquants pour se défendre des insectes. Ils donnent le goût de moutarde et peuvent irriter le ventre si on en mange trop.","symptomes":["Mal au ventre","Vomissements ou diarrhée"],"que_faire":["Rien d'urgent en général.","Si votre animal vomit beaucoup ou semble mal : appelez votre vétérinaire."],"precision":"Pas de fiche ASPCA trouvée pour le radis cultivé (le radis sauvage a une fiche à part). Selon l'AKC (avis d'un vétérinaire), les fanes peuvent donner une gastro-entérite aux chiens. Rien de confirmé pour les chats.","verifie":false,"sources":[{"titre":"AKC — Can dogs eat radishes","url":"https://www.akc.org/expert-advice/advice/can-dogs-eat-radishes/"}],"precautions":["Gardez les plantes hors de portée des jeunes enfants et des animaux.","Apprenez aux enfants à ne rien manger au jardin sans demander à un adulte.","Lavez-vous les mains après avoir jardiné."]},
 "carotte": {"niveau":"aucune","resume":"La carotte est sans danger pour les chats, les chiens et les personnes. La sève des fanes peut seulement irriter la peau de certaines personnes au soleil.","animaux":{"chats":"non","chiens":"non","autres":"Chevaux : non toxique (ASPCA)."},"humains":{"enfants":"non","adultes":"non","texte":"La racine se mange sans danger. Si vous avez la peau sensible, mettez des gants pour couper les fanes en plein soleil."},"parties":["Racine : sans danger","Fanes : sève qui peut irriter la peau"],"substances":["Psoralènes : des substances de la sève qui rendent la peau sensible au soleil."],"pourquoi":"Les plantes de la famille de la carotte fabriquent des psoralènes. Au contact de la peau puis du soleil, ils peuvent donner des rougeurs. Manger la carotte ne pose pas de problème.","symptomes":["Rougeur ou cloques sur la peau après contact avec la sève et le soleil (rare)"],"que_faire":["Si la peau rougit : lavez à l'eau et au savon, évitez le soleil.","Si la peau fait des cloques : demandez conseil à un médecin ou un pharmacien."],"precision":"L'ASPCA classe la carotte comme non toxique pour chiens, chats et chevaux et note la présence de psoralènes (irritation de la peau).","verifie":true,"sources":[{"titre":"ASPCA — Carrot Flower","url":"https://www.aspca.org/pet-care/aspca-poison-control/toxic-and-non-toxic-plants/carrot-flower"},{"titre":"ASPCA — Pets and Produce (potager)","url":"https://www.aspca.org/news/pets-and-produce-top-tips-vegetable-garden-safety"}],"precautions":["Gants et manches longues si vous avez la peau sensible.","Lavez les carottes avant de les manger."]},
 "haricot-nain": {"niveau":"moderee","resume":"Les haricots CRUS (frais ou secs) rendent malade : il faut les cuire. Cuits, ils se mangent très bien.","animaux":{"chats":"inconnu","chiens":"inconnu","autres":""},"humains":{"enfants":"oui","adultes":"oui","texte":"Mangés crus ou mal cuits, les haricots donnent de fortes nausées et des vomissements en 1 à 3 heures. Il faut les faire bouillir franchement au moins 10 minutes (les secs doivent d'abord tremper)."},"parties":["Graines crues (haricots secs ou écossés)","Gousses crues en grande quantité"],"substances":["Phytohémagglutinine : une protéine que la plante fabrique pour se défendre. Elle irrite l'intestin. La cuisson la détruit."],"pourquoi":"Les graines doivent survivre dans le sol. Elles contiennent donc une protéine qui rend malade ceux qui les mangent crues. Une cuisson à gros bouillons la détruit ; une cuisson trop douce, non.","symptomes":["Nausées très fortes","Vomissements (1 à 3 heures après)","Diarrhée","Mal au ventre"],"que_faire":["Ne faites pas vomir, sauf si un professionnel de santé le demande.","Rincez la bouche avec de l'eau. Ne forcez pas à boire ni à manger.","Appelez un centre antipoison ou votre médecin (exemple : centre antipoison d'Angers, 02 41 35 33 30). Dites ce qui a été mangé et en quelle quantité.","Si la personne se sent mal, perd connaissance ou respire mal : appelez tout de suite le 15 ou le 112.","Gardez un morceau de la plante ou prenez une photo pour le montrer."],"precision":"La source ouverte (Hong Kong) décrit les haricots rouges (Phaseolus vulgaris), les plus riches en toxine. Les haricots verts jeunes sont moins concernés mais on les cuit par prudence. Pour les animaux, l'ASPCA cite les haricots cuits comme friandise correcte ; pour les haricots crus, rien de confirmé : on les évite.","verifie":true,"sources":[{"titre":"Centre for Food Safety Hong Kong — Haricots rouges crus","url":"https://www.cfs.gov.hk/english/multimedia/multimedia_pub/multimedia_pub_fsf_208_01.html"},{"titre":"ASPCA — Pets and Produce (potager)","url":"https://www.aspca.org/news/pets-and-produce-top-tips-vegetable-garden-safety"},{"titre":"ASPCA — Foods you can safely share","url":"https://www.aspca.org/news/sharing-caring-foods-you-can-safely-share-your-pet"}],"precautions":["Faites toujours cuire les haricots, à gros bouillons, au moins 10 minutes.","Ne cuisez pas les haricots secs dans une mijoteuse à basse température.","Ne laissez pas les enfants croquer des haricots crus au jardin.","Gardez les haricots hors de portée des chats et des chiens."]},
 "haricot-grimpant": {"niveau":"moderee","resume":"Les haricots CRUS (frais ou secs) rendent malade : il faut les cuire. Cuits, ils se mangent très bien.","animaux":{"chats":"inconnu","chiens":"inconnu","autres":""},"humains":{"enfants":"oui","adultes":"oui","texte":"Mangés crus ou mal cuits, les haricots donnent de fortes nausées et des vomissements en 1 à 3 heures. Il faut les faire bouillir franchement au moins 10 minutes (les secs doivent d'abord tremper)."},"parties":["Graines crues (haricots secs ou écossés)","Gousses crues en grande quantité"],"substances":["Phytohémagglutinine : une protéine que la plante fabrique pour se défendre. Elle irrite l'intestin. La cuisson la détruit."],"pourquoi":"Les graines doivent survivre dans le sol. Elles contiennent donc une protéine qui rend malade ceux qui les mangent crues. Une cuisson à gros bouillons la détruit ; une cuisson trop douce, non.","symptomes":["Nausées très fortes","Vomissements (1 à 3 heures après)","Diarrhée","Mal au ventre"],"que_faire":["Ne faites pas vomir, sauf si un professionnel de santé le demande.","Rincez la bouche avec de l'eau. Ne forcez pas à boire ni à manger.","Appelez un centre antipoison ou votre médecin (exemple : centre antipoison d'Angers, 02 41 35 33 30). Dites ce qui a été mangé et en quelle quantité.","Si la personne se sent mal, perd connaissance ou respire mal : appelez tout de suite le 15 ou le 112.","Gardez un morceau de la plante ou prenez une photo pour le montrer."],"precision":"La source ouverte (Hong Kong) décrit les haricots rouges (Phaseolus vulgaris), les plus riches en toxine. Les haricots verts jeunes sont moins concernés mais on les cuit par prudence. Pour les animaux, l'ASPCA cite les haricots cuits comme friandise correcte ; pour les haricots crus, rien de confirmé : on les évite.","verifie":true,"sources":[{"titre":"Centre for Food Safety Hong Kong — Haricots rouges crus","url":"https://www.cfs.gov.hk/english/multimedia/multimedia_pub/multimedia_pub_fsf_208_01.html"},{"titre":"ASPCA — Pets and Produce (potager)","url":"https://www.aspca.org/news/pets-and-produce-top-tips-vegetable-garden-safety"},{"titre":"ASPCA — Foods you can safely share","url":"https://www.aspca.org/news/sharing-caring-foods-you-can-safely-share-your-pet"}],"precautions":["Faites toujours cuire les haricots, à gros bouillons, au moins 10 minutes.","Ne cuisez pas les haricots secs dans une mijoteuse à basse température.","Ne laissez pas les enfants croquer des haricots crus au jardin.","Gardez les haricots hors de portée des chats et des chiens."]},
 "poivron": {"niveau":"faible","resume":"Le poivron mûr se mange bien. Les feuilles et les fruits très verts sont à éviter pour les animaux : ils peuvent donner mal au ventre.","animaux":{"chats":"inconnu","chiens":"oui","autres":""},"humains":{"enfants":"non","adultes":"non","texte":"Le fruit se mange sans danger. On ne mange pas les feuilles."},"parties":["Feuilles","Fruits très verts (petite toxicité)"],"substances":["Alcaloïdes de la famille des morelles, en très petite quantité. Ils irritent le ventre."],"pourquoi":"Le poivron est de la même famille que la tomate et la pomme de terre. Ses feuilles contiennent un peu des mêmes substances de défense, mais bien moins que la tomate. Le fruit mûr n'en a presque plus.","symptomes":["Nausées légères","Vomissements, diarrhée","Bave"],"que_faire":["Ne faites pas vomir votre animal, sauf si un vétérinaire vous le demande.","Appelez tout de suite votre vétérinaire ou un service d'urgence vétérinaire. Dites quelle plante, quelle partie et quelle quantité.","Emportez un morceau de la plante ou une photo.","Si l'animal est très mou, tremble, ne respire pas bien ou perd connaissance : allez en urgence chez le vétérinaire."],"precision":"Pet Poison Helpline classe les légumes de la famille des morelles (aubergine, pomme de terre, tomate, poivron) comme « légèrement toxiques » (feuillage ou fruits) pour les chiens, sans parler des chats. La fiche actuelle (chatChien = false) est donc à nuancer.","verifie":true,"sources":[{"titre":"Pet Poison Helpline — Nightshade (aubergine, pomme de terre, poivron)","url":"https://www.petpoisonhelpline.com/?p=1949"},{"titre":"ASPCA — Pets and Produce (potager)","url":"https://www.aspca.org/news/pets-and-produce-top-tips-vegetable-garden-safety"}],"precautions":["Gardez les plantes hors de portée des jeunes enfants et des animaux.","Apprenez aux enfants à ne rien manger au jardin sans demander à un adulte.","Lavez-vous les mains après avoir jardiné."]},
 "piment": {"niveau":"faible","resume":"Les piments brûlent la bouche, les yeux et le ventre. Dangereux pour le confort des animaux et des enfants, rarement grave.","animaux":{"chats":"oui","chiens":"oui","autres":""},"humains":{"enfants":"oui","adultes":"non","texte":"Un piment brûle fort la bouche, l'estomac et les yeux. Ne touchez pas vos yeux après avoir touché des piments. Les petits enfants ne doivent pas en croquer."},"parties":["Fruits, surtout les graines et les cloisons blanches"],"substances":["Capsaïcine : la substance qui brûle. La plante la fabrique pour décourager les animaux de manger ses fruits."],"pourquoi":"Les piments se défendent avec la capsaïcine, qui active les capteurs de chaleur de la bouche. Elle donne une sensation de brûlure sans vraie blessure en général. En grande quantité, elle irrite le ventre.","symptomes":["Brûlure de la bouche et des yeux","Bave, larmes, se frotte le museau","Vomissements, diarrhée si beaucoup mangé","Cloques dans la bouche (piments très forts, comme l'habanero)"],"que_faire":["Rincez la bouche et les yeux longuement à l'eau claire.","Pour un animal : appelez votre vétérinaire si les signes durent ou s'il vomit beaucoup.","Pour une personne : appelez un centre antipoison ou votre médecin si la douleur dure (exemple : centre d'Angers, 02 41 35 33 30). Urgence vitale : 15 ou 112."],"precision":"Les effets sont presque toujours temporaires (source IVIS). Les piments secs mal conservés peuvent contenir des moisissures. Les convulsions n'ont été vues qu'à très fortes doses en expérience.","verifie":true,"sources":[{"titre":"IVIS — Capsicum (piments)","url":"https://www.ivis.org/library/guide-to-poisonous-house-and-garden-plants/capsicum-species-chili-pepper"},{"titre":"Pet Poison Helpline — Nightshade (aubergine, pomme de terre, poivron)","url":"https://www.petpoisonhelpline.com/?p=1949"}],"precautions":["Mettez des gants pour couper les piments forts.","Ne vous touchez pas les yeux après les avoir manipulés.","Gardez les piments hors de portée des enfants et des animaux."]},
 "aubergine": {"niveau":"faible","resume":"L'aubergine cuite se mange. Les feuilles, les tiges et les fruits crus ou verts contiennent de la solanine : à ne pas manger, surtout pour les animaux.","animaux":{"chats":"inconnu","chiens":"oui","autres":"Chevaux, bétail : les parties vertes sont toxiques (Massey)."},"humains":{"enfants":"oui","adultes":"oui","texte":"On ne mange pas les feuilles. Le fruit se mange cuit et bien mûr. La cuisson ne détruit pas la solanine, alors on évite les fruits verts ou amers."},"parties":["Feuilles","Tiges","Fruits verts ou très amers"],"substances":["Solanine : un poison de défense de la famille des morelles. Elle irrite le ventre et peut perturber le système nerveux."],"pourquoi":"L'aubergine est une morelle comme la tomate. Pour ne pas être mangée par les insectes et les animaux, elle fabrique de la solanine dans ses feuilles et ses jeunes fruits.","symptomes":["Bave, perte d'appétit","Vomissements, diarrhée, mal au ventre","Fatigue, faiblesse","Maux de tête et sueurs (chez la personne)"],"que_faire":["Ne faites pas vomir votre animal, sauf si un vétérinaire vous le demande.","Appelez tout de suite votre vétérinaire ou un service d'urgence vétérinaire. Dites quelle plante, quelle partie et quelle quantité.","Emportez un morceau de la plante ou une photo.","Pour une personne qui se sent mal : appelez un centre antipoison ou le 15 (exemple : centre d'Angers, 02 41 35 33 30)."],"precision":"Pas de fiche ASPCA trouvée pour l'aubergine. Pet Poison Helpline classe les légumes de la famille des morelles comme légèrement toxiques pour les chiens (feuillage, fruits) et ne parle pas des chats. La solanine de l'aubergine mûre est faible : le danger vient surtout des feuilles et des fruits verts.","verifie":true,"sources":[{"titre":"Pet Poison Helpline — Nightshade (aubergine, pomme de terre, poivron)","url":"https://www.petpoisonhelpline.com/?p=1949"},{"titre":"La Revue du Praticien — Intoxication à la solanine","url":"https://www.larevuedupraticien.fr/article/intoxication-la-solanine"}],"precautions":["Gardez les plantes hors de portée des jeunes enfants et des animaux.","Apprenez aux enfants à ne rien manger au jardin sans demander à un adulte.","Lavez-vous les mains après avoir jardiné."]},
 "concombre": {"niveau":"aucune","resume":"Le concombre n'est pas toxique pour les chats et les chiens (ASPCA). Aucun danger connu pour les personnes en quantité normale.","animaux":{"chats":"non","chiens":"non","autres":"Chevaux : non toxique (ASPCA)."},"humains":{"enfants":"non","adultes":"non","texte":"Se mange sans danger. Si un concombre est très amer, ne le mangez pas."},"parties":["Aucune partie connue comme toxique"],"substances":["Aucune substance dangereuse connue à dose normale."],"pourquoi":"Cette plante n'est pas connue pour être dangereuse. Comme toute plante, trop en manger peut seulement dérégler le ventre d'un animal.","symptomes":["Rien en général","Ventre un peu dérangé si l'animal en mange beaucoup"],"que_faire":["Rien d'urgent en général.","Si l'animal vomit beaucoup ou semble mal : appelez votre vétérinaire."],"precision":"L'ASPCA classe le concombre (Cucumis sativus) comme non toxique.","verifie":true,"sources":[{"titre":"ASPCA — Cucumber","url":"https://www.aspca.org/pet-care/aspca-poison-control/toxic-and-non-toxic-plants/cucumber"}],"precautions":["Gardez les plantes hors de portée des jeunes enfants et des animaux.","Apprenez aux enfants à ne rien manger au jardin sans demander à un adulte.","Lavez-vous les mains après avoir jardiné."]},
 "pomme-de-terre": {"niveau":"moderee","resume":"Les pommes de terre VERTES ou germées, les feuilles et les baies sont toxiques. Une pomme de terre saine et cuite se mange sans danger.","animaux":{"chats":"oui","chiens":"oui","autres":"Chevaux, bétail : la pomme de terre et ses parties vertes sont toxiques (Massey)."},"humains":{"enfants":"oui","adultes":"oui","texte":"Ne mangez jamais une pomme de terre verte, amère ou avec de grosses pousses. La cuisson ne détruit pas la solanine : on coupe et on jette les parties vertes et les germes. Ne mangez pas les petites boules vertes des fleurs."},"parties":["Tubercules devenus verts (lumière)","Germes (pousses)","Feuilles et tiges","Baies vertes (petites boules)"],"substances":["Solanine et chaconine : des poisons de défense. Ils irritent le ventre, détruisent des globules rouges et peuvent atteindre le cerveau et le cœur."],"pourquoi":"Quand une pomme de terre reçoit de la lumière, elle verdit et fabrique plus de solanine pour se protéger. Les germes et les feuilles en contiennent aussi beaucoup. Ces poisons irritent l'intestin et, en grande quantité, agissent sur le système nerveux et le cœur.","symptomes":["Bouche qui gratte ou brûle, goût amer","Nausées, vomissements, diarrhée, mal au ventre (en général 7 à 14 heures après)","Maux de tête, sueurs, fièvre","Animaux : bave, faiblesse, pupilles dilatées, cœur lent","Cas graves : confusion, perte de connaissance, difficultés à respirer"],"que_faire":["Ne faites pas vomir, sauf si un professionnel de santé le demande.","Rincez la bouche avec de l'eau. Ne forcez pas à boire ni à manger.","Appelez un centre antipoison ou votre médecin (exemple : centre antipoison d'Angers, 02 41 35 33 30). Dites ce qui a été mangé et en quelle quantité.","Si la personne se sent mal, perd connaissance ou respire mal : appelez tout de suite le 15 ou le 112.","Gardez un morceau de la plante ou prenez une photo pour le montrer."],"precision":"Des doses de 3 à 6 mg de glycoalcaloïdes par kilo peuvent être mortelles chez l'humain, mais les cas graves sont rares. L'ASPCA ne détaille pas la pomme de terre ; les infos animales viennent surtout de l'université Massey et de Pet Poison Helpline (famille des morelles).","verifie":true,"sources":[{"titre":"Massey University — Potato (plantes toxiques)","url":"https://poisonousplants.massey.ac.nz/data/potato/potato.html"},{"titre":"La Revue du Praticien — Intoxication à la solanine","url":"https://www.larevuedupraticien.fr/article/intoxication-la-solanine"},{"titre":"Pet Poison Helpline — Nightshade (aubergine, pomme de terre, poivron)","url":"https://www.petpoisonhelpline.com/?p=1949"},{"titre":"ASPCA — Pets and Produce (potager)","url":"https://www.aspca.org/news/pets-and-produce-top-tips-vegetable-garden-safety"}],"precautions":["Gardez les pommes de terre à l'obscurité, au frais, à l'abri de la lumière.","Épluchez bien et coupez toutes les parties vertes et les germes.","Jetez les pommes de terre très vertes, amères ou très germées.","Ne laissez pas les enfants croquer les baies ou les feuilles.","Gardez les pommes de terre crues hors de portée des animaux."]},
 "ail": {"niveau":"moderee","resume":"Dangereux pour les CHATS et les CHIENS, même cuit. Les chats sont les plus fragiles. Pour les personnes, c'est un aliment normal.","animaux":{"chats":"oui","chiens":"oui","autres":"Chevaux : toxique (ASPCA)."},"humains":{"enfants":"non","adultes":"non","texte":"Se mange sans danger pour les personnes. Le danger concerne seulement les chats, les chiens et les chevaux."},"parties":["Bulbe (gousses)","Feuilles","Poudre, ail séché ou cuit"],"substances":["Composés soufrés (N-propyl disulfure) : ils abîment les globules rouges du sang des chats et des chiens, qui deviennent trop fragiles."],"pourquoi":"Les plantes de la famille de l'oignon fabriquent des composés soufrés pour se défendre. Chez le chat et le chien, ils attaquent les globules rouges, qui transportent l'oxygène. L'animal peut devenir anémié quelques jours après avoir mangé. Le cru, le cuit, la poudre et le séché sont tous dangereux.","symptomes":["Vomissements, perte d'appétit","Fatigue, faiblesse, gencives pâles","Respiration et cœur rapides","Urine foncée ou rouge","Jaunisse, effondrement (cas graves)","Les signes apparaissent souvent un à plusieurs jours plus tard"],"que_faire":["Ne faites pas vomir votre animal, sauf si un vétérinaire vous le demande.","Appelez tout de suite votre vétérinaire ou un service d'urgence vétérinaire. Dites quelle plante, quelle partie et quelle quantité.","Appelez le vétérinaire même si l'animal va bien : les signes arrivent parfois plus tard.","Emportez l'emballage ou une photo de ce qui a été mangé."],"precision":"Selon le MSD Vet Manual, l'ail est 3 à 5 fois plus toxique que l'oignon à poids égal. Même une petite quantité est à éviter pour un chat.","verifie":true,"sources":[{"titre":"ASPCA — Garlic","url":"https://www.aspca.org/pet-care/aspca-poison-control/toxic-and-non-toxic-plants/garlic"},{"titre":"MSD Vet Manual — Allium toxicosis in animals","url":"https://www.msdvetmanual.com/toxicology/food-hazards/allium-spp-toxicosis-in-animals"},{"titre":"Pet Poison Helpline — Onions, garlic, chives, leeks","url":"https://www.petpoisonhelpline.com/pet-safety-tips/are-onions-poisons-to-dogs/"},{"titre":"ASPCA — People foods to avoid feeding your pets","url":"https://www.aspca.org/pet-care/aspca-poison-control/people-foods-avoid-feeding-your-pets"}],"precautions":["Ne donnez jamais de restes de repas avec ail, oignon, poireau ou ciboulette à un animal.","Gardez ces plantes et les épluchures hors de portée.","Mettez un grillage autour du carré du potager si votre chien ou votre chat creuse.","Attention aux soupes en sachet, poudres et plats cuisinés."]},
 "oignon": {"niveau":"moderee","resume":"Dangereux pour les CHATS et les CHIENS, même cuit. Les chats sont les plus fragiles. Pour les personnes, c'est un aliment normal.","animaux":{"chats":"oui","chiens":"oui","autres":"Chevaux : toxique (ASPCA)."},"humains":{"enfants":"non","adultes":"non","texte":"Se mange sans danger pour les personnes. Le danger concerne seulement les chats, les chiens et les chevaux."},"parties":["Bulbe","Feuilles","Poudre, oignon séché ou cuit"],"substances":["Composés soufrés (N-propyl disulfure) : ils abîment les globules rouges du sang des chats et des chiens, qui deviennent trop fragiles."],"pourquoi":"Les plantes de la famille de l'oignon fabriquent des composés soufrés pour se défendre. Chez le chat et le chien, ils attaquent les globules rouges, qui transportent l'oxygène. L'animal peut devenir anémié quelques jours après avoir mangé. Le cru, le cuit, la poudre et le séché sont tous dangereux.","symptomes":["Vomissements, perte d'appétit","Fatigue, faiblesse, gencives pâles","Respiration et cœur rapides","Urine foncée ou rouge","Jaunisse, effondrement (cas graves)","Les signes apparaissent souvent un à plusieurs jours plus tard"],"que_faire":["Ne faites pas vomir votre animal, sauf si un vétérinaire vous le demande.","Appelez tout de suite votre vétérinaire ou un service d'urgence vétérinaire. Dites quelle plante, quelle partie et quelle quantité.","Appelez le vétérinaire même si l'animal va bien : les signes arrivent parfois plus tard.","Emportez l'emballage ou une photo de ce qui a été mangé."],"precision":"Selon le MSD Vet Manual, l'ail est 3 à 5 fois plus toxique que l'oignon à poids égal. Les chats ont été intoxiqués par moins d'une cuillère à café d'oignon cuit ; chez le chien, les signes sont apparus avec 15 à 30 g d'oignon cru par kilo.","verifie":true,"sources":[{"titre":"ASPCA — Onion","url":"https://www.aspca.org/node/5196"},{"titre":"MSD Vet Manual — Allium toxicosis in animals","url":"https://www.msdvetmanual.com/toxicology/food-hazards/allium-spp-toxicosis-in-animals"},{"titre":"Pet Poison Helpline — Onions, garlic, chives, leeks","url":"https://www.petpoisonhelpline.com/pet-safety-tips/are-onions-poisons-to-dogs/"},{"titre":"ASPCA — People foods to avoid feeding your pets","url":"https://www.aspca.org/pet-care/aspca-poison-control/people-foods-avoid-feeding-your-pets"}],"precautions":["Ne donnez jamais de restes de repas avec ail, oignon, poireau ou ciboulette à un animal.","Gardez ces plantes et les épluchures hors de portée.","Mettez un grillage autour du carré du potager si votre chien ou votre chat creuse.","Attention aux soupes en sachet, poudres et plats cuisinés."]},
 "echalote": {"niveau":"moderee","resume":"Dangereux pour les CHATS et les CHIENS, même cuit. Les chats sont les plus fragiles. Pour les personnes, c'est un aliment normal.","animaux":{"chats":"oui","chiens":"oui","autres":"Chevaux : toxique (ASPCA)."},"humains":{"enfants":"non","adultes":"non","texte":"Se mange sans danger pour les personnes. Le danger concerne seulement les chats, les chiens et les chevaux."},"parties":["Bulbe","Feuilles","Poudre, échalote séchée ou cuite"],"substances":["Composés soufrés (N-propyl disulfure) : ils abîment les globules rouges du sang des chats et des chiens, qui deviennent trop fragiles."],"pourquoi":"Les plantes de la famille de l'oignon fabriquent des composés soufrés pour se défendre. Chez le chat et le chien, ils attaquent les globules rouges, qui transportent l'oxygène. L'animal peut devenir anémié quelques jours après avoir mangé. Le cru, le cuit, la poudre et le séché sont tous dangereux.","symptomes":["Vomissements, perte d'appétit","Fatigue, faiblesse, gencives pâles","Respiration et cœur rapides","Urine foncée ou rouge","Jaunisse, effondrement (cas graves)","Les signes apparaissent souvent un à plusieurs jours plus tard"],"que_faire":["Ne faites pas vomir votre animal, sauf si un vétérinaire vous le demande.","Appelez tout de suite votre vétérinaire ou un service d'urgence vétérinaire. Dites quelle plante, quelle partie et quelle quantité.","Appelez le vétérinaire même si l'animal va bien : les signes arrivent parfois plus tard.","Emportez l'emballage ou une photo de ce qui a été mangé."],"precision":"Pas de fiche ASPCA propre à l'échalote : par prudence, on la traite comme l'oignon (même plante, Allium cepa). Le MSD Vet Manual ne la détaille pas non plus.","verifie":true,"sources":[{"titre":"ASPCA — Onion","url":"https://www.aspca.org/node/5196"},{"titre":"MSD Vet Manual — Allium toxicosis in animals","url":"https://www.msdvetmanual.com/toxicology/food-hazards/allium-spp-toxicosis-in-animals"},{"titre":"Pet Poison Helpline — Onions, garlic, chives, leeks","url":"https://www.petpoisonhelpline.com/pet-safety-tips/are-onions-poisons-to-dogs/"}],"precautions":["Ne donnez jamais de restes de repas avec ail, oignon, poireau ou ciboulette à un animal.","Gardez ces plantes et les épluchures hors de portée.","Mettez un grillage autour du carré du potager si votre chien ou votre chat creuse.","Attention aux soupes en sachet, poudres et plats cuisinés."]},
 "epinard": {"niveau":"faible","resume":"L'épinard se mange. En très grande quantité, il peut gêner les reins à cause de l'acide oxalique. Pour les animaux : petites quantités seulement.","animaux":{"chats":"inconnu","chiens":"non","autres":""},"humains":{"enfants":"non","adultes":"non","texte":"Se mange sans danger dans une alimentation normale. Les personnes qui ont eu des calculs rénaux doivent demander conseil à leur médecin."},"parties":["Feuilles, surtout en grande quantité"],"substances":["Acide oxalique (oxalates) : il retient le calcium et peut former de petits cristaux dans les reins s'il y en a trop."],"pourquoi":"L'épinard fabrique de l'acide oxalique, qui lui donne un goût un peu râpeux. Il se lie au calcium et, en excès, peut fatiguer les reins.","symptomes":["Ventre dérangé en grande quantité","Chez l'animal, très gros excès : faiblesse, problèmes de reins"],"que_faire":["Rien d'urgent pour une petite quantité.","Si votre animal en a mangé beaucoup et semble mal : appelez votre vétérinaire."],"precision":"Pas de fiche ASPCA trouvée pour l'épinard. Selon l'AKC, petite quantité acceptable pour un chien sans problème de reins ; rien de confirmé pour les chats.","verifie":false,"sources":[{"titre":"AKC — Can dogs eat spinach","url":"https://www.akc.org/expert-advice/nutrition/can-dogs-eat-spinach/"}],"precautions":["Gardez les plantes hors de portée des jeunes enfants et des animaux.","Apprenez aux enfants à ne rien manger au jardin sans demander à un adulte.","Lavez-vous les mains après avoir jardiné."]},
 "poireau": {"niveau":"moderee","resume":"Dangereux pour les CHATS et les CHIENS, même cuit. Les chats sont les plus fragiles. Pour les personnes, c'est un aliment normal.","animaux":{"chats":"oui","chiens":"oui","autres":"Chevaux : toxique (ASPCA)."},"humains":{"enfants":"non","adultes":"non","texte":"Se mange sans danger pour les personnes. Le danger concerne seulement les chats, les chiens et les chevaux."},"parties":["Blanc et vert (toute la plante)","Poireau cuit (soupes, restes)"],"substances":["Composés soufrés (N-propyl disulfure) : ils abîment les globules rouges du sang des chats et des chiens, qui deviennent trop fragiles."],"pourquoi":"Les plantes de la famille de l'oignon fabriquent des composés soufrés pour se défendre. Chez le chat et le chien, ils attaquent les globules rouges, qui transportent l'oxygène. L'animal peut devenir anémié quelques jours après avoir mangé. Le cru, le cuit, la poudre et le séché sont tous dangereux.","symptomes":["Vomissements, perte d'appétit","Fatigue, faiblesse, gencives pâles","Respiration et cœur rapides","Urine foncée ou rouge","Jaunisse, effondrement (cas graves)","Les signes apparaissent souvent un à plusieurs jours plus tard"],"que_faire":["Ne faites pas vomir votre animal, sauf si un vétérinaire vous le demande.","Appelez tout de suite votre vétérinaire ou un service d'urgence vétérinaire. Dites quelle plante, quelle partie et quelle quantité.","Appelez le vétérinaire même si l'animal va bien : les signes arrivent parfois plus tard.","Emportez l'emballage ou une photo de ce qui a été mangé."],"precision":"Selon le MSD Vet Manual, l'ail est 3 à 5 fois plus toxique que l'oignon à poids égal. Les chats ont été intoxiqués par moins d'une cuillère à café d'oignon cuit ; chez le chien, les signes sont apparus avec 15 à 30 g d'oignon cru par kilo.","verifie":true,"sources":[{"titre":"ASPCA — Leek","url":"https://www.aspca.org/pet-care/aspca-poison-control/toxic-and-non-toxic-plants/leek"},{"titre":"MSD Vet Manual — Allium toxicosis in animals","url":"https://www.msdvetmanual.com/toxicology/food-hazards/allium-spp-toxicosis-in-animals"},{"titre":"Pet Poison Helpline — Onions, garlic, chives, leeks","url":"https://www.petpoisonhelpline.com/pet-safety-tips/are-onions-poisons-to-dogs/"}],"precautions":["Ne donnez jamais de restes de repas avec ail, oignon, poireau ou ciboulette à un animal.","Gardez ces plantes et les épluchures hors de portée.","Mettez un grillage autour du carré du potager si votre chien ou votre chat creuse.","Attention aux soupes en sachet, poudres et plats cuisinés."]},
 "betterave": {"niveau":"aucune","resume":"La betterave est sans danger pour les chats, les chiens et les personnes. Les grandes feuilles contiennent de l'acide oxalique : pas en grande quantité.","animaux":{"chats":"non","chiens":"non","autres":"Chevaux : non toxique (ASPCA)."},"humains":{"enfants":"non","adultes":"non","texte":"Racine et jeunes feuilles se mangent sans danger."},"parties":["Grandes feuilles âgées (un peu d'acide oxalique)"],"substances":["Acide oxalique : en très grande quantité, il gêne les reins."],"pourquoi":"La betterave fabrique de l'acide oxalique dans ses grandes feuilles. À petite dose, cela ne pose pas de problème.","symptomes":["Rien en petite quantité"],"que_faire":["Rien d'urgent.","Si un doute : appelez votre vétérinaire."],"precision":"L'ASPCA liste la betterave comme non toxique mais note que les grandes feuilles mûres contiennent de l'acide oxalique.","verifie":true,"sources":[{"titre":"ASPCA — Beets","url":"https://www.aspca.org/pet-care/aspca-poison-control/toxic-and-non-toxic-plants/beets"}],"precautions":["Gardez les plantes hors de portée des jeunes enfants et des animaux.","Apprenez aux enfants à ne rien manger au jardin sans demander à un adulte.","Lavez-vous les mains après avoir jardiné."]},
 "chou-kale": {"niveau":"faible","resume":"Le chou kale se mange. Pour les chiens, en petite quantité seulement. Pour les chats, la confirmation manque.","animaux":{"chats":"inconnu","chiens":"non","autres":""},"humains":{"enfants":"non","adultes":"non","texte":"Se mange sans danger en quantité normale."},"parties":["Feuilles, en grande quantité"],"substances":["Oxalates et isothiocyanates : des substances de défense qui irritent le ventre et peuvent gêner la thyroïde en excès."],"pourquoi":"Comme les autres choux, le kale fabrique des substances piquantes qui éloignent les insectes. À grande dose et souvent, elles irritent l'estomac.","symptomes":["Ventre dérangé, vomissements","Difficulté ou changement pour uriner (en excès, chez les chiens à risque)"],"que_faire":["Rien d'urgent en petite quantité.","Si votre animal vomit ou urine mal : appelez votre vétérinaire."],"precision":"Pas de fiche ASPCA trouvée pour le kale. Selon l'AKC, il n'est pas recommandé en habitude pour les chiens (oxalates, isothiocyanates). Rien de confirmé pour les chats.","verifie":false,"sources":[{"titre":"AKC — Can dogs eat kale","url":"https://www.akc.org/expert-advice/nutrition/can-dogs-eat-kale/"}],"precautions":["Gardez les plantes hors de portée des jeunes enfants et des animaux.","Apprenez aux enfants à ne rien manger au jardin sans demander à un adulte.","Lavez-vous les mains après avoir jardiné."]},
 "basilic": {"niveau":"aucune","resume":"Le basilic n'est pas toxique pour les chats et les chiens (ASPCA). Aucun danger connu pour les personnes en quantité normale.","animaux":{"chats":"non","chiens":"non","autres":""},"humains":{"enfants":"non","adultes":"non","texte":"Se mange sans danger comme aromate."},"parties":["Aucune partie connue comme toxique"],"substances":["Aucune substance dangereuse connue à dose normale."],"pourquoi":"Cette plante n'est pas connue pour être dangereuse. Comme toute plante, trop en manger peut seulement dérégler le ventre d'un animal.","symptomes":["Rien en général","Ventre un peu dérangé si l'animal en mange beaucoup"],"que_faire":["Rien d'urgent en général.","Si l'animal vomit beaucoup ou semble mal : appelez votre vétérinaire."],"precision":"L'ASPCA ne se prononce pas pour les chevaux sur sa page du basilic.","verifie":true,"sources":[{"titre":"ASPCA — Basil","url":"https://www.aspca.org/pet-care/aspca-poison-control/toxic-and-non-toxic-plants/basil"}],"precautions":["Gardez les plantes hors de portée des jeunes enfants et des animaux.","Apprenez aux enfants à ne rien manger au jardin sans demander à un adulte.","Lavez-vous les mains après avoir jardiné."]},
 "persil": {"niveau":"faible","resume":"En petite quantité, le persil ne gêne pas. En grande quantité, il peut rendre la peau des chats et des chiens sensible au soleil. Pour les personnes, c'est un aromate normal.","animaux":{"chats":"oui","chiens":"oui","autres":"Chevaux : toxique (ASPCA)."},"humains":{"enfants":"non","adultes":"non","texte":"Se mange sans danger comme aromate. Si la sève touche la peau puis le soleil, certaines personnes peuvent avoir des rougeurs."},"parties":["Feuilles et tiges en grande quantité"],"substances":["Furanocoumarines : des substances qui rendent la peau sensible au soleil (comme un coup de soleil)."],"pourquoi":"Le persil fait partie de la famille de la carotte et de l'aneth. Ces plantes fabriquent des furanocoumarines pour se défendre. Elles ne posent problème qu'en grande quantité.","symptomes":["Peau rouge ou irritée au soleil","Ventre un peu dérangé"],"que_faire":["Ne faites pas vomir votre animal, sauf si un vétérinaire vous le demande.","Appelez tout de suite votre vétérinaire ou un service d'urgence vétérinaire. Dites quelle plante, quelle partie et quelle quantité.","Emportez un morceau de la plante ou une photo.","Si l'animal est très mou, tremble, ne respire pas bien ou perd connaissance : allez en urgence chez le vétérinaire."],"precision":"L'ASPCA le classe « toxique » pour chiens, chats et chevaux mais précise qu'il faut une grande quantité.","verifie":true,"sources":[{"titre":"ASPCA — Parsley","url":"https://www.aspca.org/pet-care/aspca-poison-control/toxic-and-non-toxic-plants/parsley"}],"precautions":["Gardez les plantes hors de portée des jeunes enfants et des animaux.","Apprenez aux enfants à ne rien manger au jardin sans demander à un adulte.","Lavez-vous les mains après avoir jardiné."]},
 "ciboulette": {"niveau":"moderee","resume":"Dangereux pour les CHATS et les CHIENS, même cuit. Les chats sont les plus fragiles. Pour les personnes, c'est un aliment normal.","animaux":{"chats":"oui","chiens":"oui","autres":"Chevaux : toxique (ASPCA)."},"humains":{"enfants":"non","adultes":"non","texte":"Se mange sans danger pour les personnes. Le danger concerne seulement les chats, les chiens et les chevaux."},"parties":["Feuilles fines (tiges creuses)","Fleurs","Ciboulette séchée"],"substances":["Composés soufrés (N-propyl disulfure) : ils abîment les globules rouges du sang des chats et des chiens, qui deviennent trop fragiles."],"pourquoi":"Les plantes de la famille de l'oignon fabriquent des composés soufrés pour se défendre. Chez le chat et le chien, ils attaquent les globules rouges, qui transportent l'oxygène. L'animal peut devenir anémié quelques jours après avoir mangé. Le cru, le cuit, la poudre et le séché sont tous dangereux.","symptomes":["Vomissements, perte d'appétit","Fatigue, faiblesse, gencives pâles","Respiration et cœur rapides","Urine foncée ou rouge","Jaunisse, effondrement (cas graves)","Les signes apparaissent souvent un à plusieurs jours plus tard"],"que_faire":["Ne faites pas vomir votre animal, sauf si un vétérinaire vous le demande.","Appelez tout de suite votre vétérinaire ou un service d'urgence vétérinaire. Dites quelle plante, quelle partie et quelle quantité.","Appelez le vétérinaire même si l'animal va bien : les signes arrivent parfois plus tard.","Emportez l'emballage ou une photo de ce qui a été mangé."],"precision":"Selon le MSD Vet Manual, l'ail est 3 à 5 fois plus toxique que l'oignon à poids égal. Les chats ont été intoxiqués par moins d'une cuillère à café d'oignon cuit ; chez le chien, les signes sont apparus avec 15 à 30 g d'oignon cru par kilo.","verifie":true,"sources":[{"titre":"ASPCA — Chives","url":"https://www.aspca.org/pet-care/aspca-poison-control/toxic-and-non-toxic-plants/chives"},{"titre":"MSD Vet Manual — Allium toxicosis in animals","url":"https://www.msdvetmanual.com/toxicology/food-hazards/allium-spp-toxicosis-in-animals"},{"titre":"Pet Poison Helpline — Onions, garlic, chives, leeks","url":"https://www.petpoisonhelpline.com/pet-safety-tips/are-onions-poisons-to-dogs/"}],"precautions":["Ne donnez jamais de restes de repas avec ail, oignon, poireau ou ciboulette à un animal.","Gardez ces plantes et les épluchures hors de portée.","Mettez un grillage autour du carré du potager si votre chien ou votre chat creuse.","Attention aux soupes en sachet, poudres et plats cuisinés."]},
 "menthe": {"niveau":"faible","resume":"En petite quantité, la menthe ne gêne pas. En grande quantité, elle peut donner vomissements et diarrhée aux chats et aux chiens.","animaux":{"chats":"oui","chiens":"oui","autres":"Chevaux : toxique (ASPCA)."},"humains":{"enfants":"non","adultes":"non","texte":"Se mange et se boit en infusion sans danger en quantité normale."},"parties":["Feuilles et tiges en grande quantité"],"substances":["Huiles essentielles (menthol) : elles irritent l'estomac des animaux en grande quantité."],"pourquoi":"La menthe fabrique des huiles aromatiques pour éloigner les insectes et les animaux. Ces huiles irritent le ventre si l'animal mange beaucoup de plante.","symptomes":["Vomissements","Diarrhée"],"que_faire":["Ne faites pas vomir votre animal, sauf si un vétérinaire vous le demande.","Appelez tout de suite votre vétérinaire ou un service d'urgence vétérinaire. Dites quelle plante, quelle partie et quelle quantité.","Emportez un morceau de la plante ou une photo.","Si l'animal est très mou, tremble, ne respire pas bien ou perd connaissance : allez en urgence chez le vétérinaire."],"precision":"L'ASPCA parle de « menthe de jardin » (Mentha sp.) et de grosses quantités. Les huiles essentielles pures sont bien plus dangereuses que la plante : non détaillé ici.","verifie":true,"sources":[{"titre":"ASPCA — Mint","url":"https://www.aspca.org/pet-care/animal-poison-control/toxic-and-non-toxic-plants/mint"}],"precautions":["Gardez les plantes hors de portée des jeunes enfants et des animaux.","Apprenez aux enfants à ne rien manger au jardin sans demander à un adulte.","Lavez-vous les mains après avoir jardiné."]},
 "thym": {"niveau":"faible","resume":"Le thym commun se mange comme aromate. Pour les chats, la confirmation manque. Ne pas confondre avec le thym d'Espagne (autre plante), toxique pour les animaux.","animaux":{"chats":"inconnu","chiens":"non","autres":""},"humains":{"enfants":"non","adultes":"non","texte":"Se mange sans danger comme aromate."},"parties":["Feuilles et tiges"],"substances":["Huiles essentielles (thymol) : irritantes pour l'estomac en grande quantité, surtout pures."],"pourquoi":"Le thym fabrique des huiles aromatiques pour se défendre des insectes. À petite dose, c'est sans problème ; en grande quantité elles irritent le ventre.","symptomes":["Ventre dérangé, vomissements en grande quantité"],"que_faire":["Rien d'urgent en petite quantité.","Si l'animal vomit beaucoup ou a mangé de l'huile essentielle : appelez votre vétérinaire."],"precision":"Pas de fiche ASPCA trouvée pour le thym commun (Thymus vulgaris) : la fiche ASPCA trouvée concerne le thym d'Espagne. Une source grand public (MasterClass) le juge sans danger pour les chiens en petite quantité. Rien de confirmé pour les chats. Fiche actuelle (chatChien = false) : probablement juste pour le chien, à confirmer pour le chat.","verifie":false,"sources":[{"titre":"MasterClass — Can dogs eat thyme","url":"https://www.masterclass.com/articles/can-dogs-eat-thyme"}],"precautions":["Gardez les plantes hors de portée des jeunes enfants et des animaux.","Apprenez aux enfants à ne rien manger au jardin sans demander à un adulte.","Lavez-vous les mains après avoir jardiné."]},
 "romarin": {"niveau":"aucune","resume":"Le romarin n'est pas toxique pour les chats et les chiens (ASPCA). Aucun danger connu pour les personnes en quantité normale.","animaux":{"chats":"non","chiens":"non","autres":"Chevaux : non toxique (ASPCA)."},"humains":{"enfants":"non","adultes":"non","texte":"Se mange sans danger comme aromate."},"parties":["Aucune partie connue comme toxique"],"substances":["Aucune substance dangereuse connue à dose normale."],"pourquoi":"Cette plante n'est pas connue pour être dangereuse. Comme toute plante, trop en manger peut seulement dérégler le ventre d'un animal.","symptomes":["Rien en général","Ventre un peu dérangé si l'animal en mange beaucoup"],"que_faire":["Rien d'urgent en général.","Si l'animal vomit beaucoup ou semble mal : appelez votre vétérinaire."],"precision":"Les huiles essentielles sont une autre chose que la plante entière : pas de preuve ici sur leur sécurité, on les tient hors de portée.","verifie":true,"sources":[{"titre":"ASPCA — Rosemary","url":"https://www.aspca.org/pet-care/aspca-poison-control/toxic-and-non-toxic-plants/rosemary"}],"precautions":["Gardez les plantes hors de portée des jeunes enfants et des animaux.","Apprenez aux enfants à ne rien manger au jardin sans demander à un adulte.","Lavez-vous les mains après avoir jardiné."]},
 "sauge": {"niveau":"aucune","resume":"La sauge n'est pas toxique pour les chats et les chiens (ASPCA). Aucun danger connu pour les personnes en quantité normale.","animaux":{"chats":"non","chiens":"non","autres":"Chevaux : non toxique (ASPCA)."},"humains":{"enfants":"non","adultes":"non","texte":"Se mange sans danger comme aromate."},"parties":["Aucune partie connue comme toxique"],"substances":["Aucune substance dangereuse connue à dose normale."],"pourquoi":"Cette plante n'est pas connue pour être dangereuse. Comme toute plante, trop en manger peut seulement dérégler le ventre d'un animal.","symptomes":["Rien en général","Ventre un peu dérangé si l'animal en mange beaucoup"],"que_faire":["Rien d'urgent en général.","Si l'animal vomit beaucoup ou semble mal : appelez votre vétérinaire."],"precision":"Sauge officinale (Salvia officinalis). Les huiles essentielles de sauge sont fortes : non vérifiées ici.","verifie":true,"sources":[{"titre":"ASPCA — Sage","url":"https://www.aspca.org/pet-care/aspca-poison-control/toxic-and-non-toxic-plants/sage"}],"precautions":["Gardez les plantes hors de portée des jeunes enfants et des animaux.","Apprenez aux enfants à ne rien manger au jardin sans demander à un adulte.","Lavez-vous les mains après avoir jardiné."]},
 "coriandre": {"niveau":"aucune","resume":"La coriandre n'est pas toxique pour les chats et les chiens (ASPCA). Aucun danger connu pour les personnes en quantité normale.","animaux":{"chats":"non","chiens":"non","autres":"Chevaux : non toxique (ASPCA)."},"humains":{"enfants":"non","adultes":"non","texte":"Se mange sans danger comme aromate."},"parties":["Aucune partie connue comme toxique"],"substances":["Aucune substance dangereuse connue à dose normale."],"pourquoi":"Cette plante n'est pas connue pour être dangereuse. Comme toute plante, trop en manger peut seulement dérégler le ventre d'un animal.","symptomes":["Rien en général","Ventre un peu dérangé si l'animal en mange beaucoup"],"que_faire":["Rien d'urgent en général.","Si l'animal vomit beaucoup ou semble mal : appelez votre vétérinaire."],"precision":"","verifie":true,"sources":[{"titre":"ASPCA — Cilantro","url":"https://www.aspca.org/pet-care/aspca-poison-control/toxic-and-non-toxic-plants/cilantro"}],"precautions":["Gardez les plantes hors de portée des jeunes enfants et des animaux.","Apprenez aux enfants à ne rien manger au jardin sans demander à un adulte.","Lavez-vous les mains après avoir jardiné."]},
 "aneth": {"niveau":"aucune","resume":"L'aneth n'est pas toxique pour les chats et les chiens (ASPCA). Aucun danger connu pour les personnes en quantité normale.","animaux":{"chats":"non","chiens":"non","autres":"Chevaux : non toxique (ASPCA)."},"humains":{"enfants":"non","adultes":"non","texte":"Se mange sans danger comme aromate. Le contact prolongé de la sève avec la peau peut parfois irriter."},"parties":["Aucune partie connue comme toxique"],"substances":["Aucune substance dangereuse connue à dose normale."],"pourquoi":"Cette plante n'est pas connue pour être dangereuse. Comme toute plante, trop en manger peut seulement dérégler le ventre d'un animal.","symptomes":["Rien en général","Ventre un peu dérangé si l'animal en mange beaucoup"],"que_faire":["Rien d'urgent en général.","Si l'animal vomit beaucoup ou semble mal : appelez votre vétérinaire."],"precision":"L'ASPCA note que les huiles essentielles de l'aneth peuvent irriter la peau en contact prolongé.","verifie":true,"sources":[{"titre":"ASPCA — Dill","url":"https://www.aspca.org/pet-care/aspca-poison-control/toxic-and-non-toxic-plants/dill"}],"precautions":["Mettez des gants si vous avez la peau sensible.","Lavez-vous les mains après avoir jardiné."]},
 "origan": {"niveau":"faible","resume":"Peut irriter le ventre des chats et des chiens (vomissements, diarrhée légers). Aromate normal pour les personnes.","animaux":{"chats":"oui","chiens":"oui","autres":"Chevaux : toxique (ASPCA)."},"humains":{"enfants":"non","adultes":"non","texte":"Se mange sans danger comme aromate."},"parties":["Feuilles et tiges"],"substances":["Irritants pour le ventre (huiles essentielles) : ils donnent des vomissements et de la diarrhée à l'animal."],"pourquoi":"L'origan fabrique des huiles aromatiques piquantes qui éloignent les insectes. Pour un animal, ces huiles irritent l'estomac.","symptomes":["Vomissements légers","Diarrhée"],"que_faire":["Ne faites pas vomir votre animal, sauf si un vétérinaire vous le demande.","Appelez tout de suite votre vétérinaire ou un service d'urgence vétérinaire. Dites quelle plante, quelle partie et quelle quantité.","Emportez un morceau de la plante ou une photo.","Si l'animal est très mou, tremble, ne respire pas bien ou perd connaissance : allez en urgence chez le vétérinaire."],"precision":"Fiche ASPCA : origan grec (Origanum vulgare hirtum). Les huiles essentielles d'origan pures sont plus dangereuses : non détaillé ici.","verifie":true,"sources":[{"titre":"ASPCA — Oregano","url":"https://www.aspca.org/pet-care/aspca-poison-control/toxic-and-non-toxic-plants/oregano"}],"precautions":["Gardez les plantes hors de portée des jeunes enfants et des animaux.","Apprenez aux enfants à ne rien manger au jardin sans demander à un adulte.","Lavez-vous les mains après avoir jardiné."]},
 "laurier-sauce": {"niveau":"faible","resume":"Peut donner vomissements et diarrhée aux chats et aux chiens, et une feuille entière avalée peut boucher l'intestin. Ne pas confondre avec le laurier-cerise, toxique.","animaux":{"chats":"oui","chiens":"oui","autres":"Chevaux : toxique (ASPCA)."},"humains":{"enfants":"non","adultes":"non","texte":"Le laurier-sauce se mange en feuille d'aromate (on retire la feuille du plat avant de manger). Le laurier-cerise, lui, est toxique : ne mettez jamais ses feuilles dans un plat."},"parties":["Feuilles (entières ou en morceaux)"],"substances":["Eugénol et autres huiles essentielles : elles irritent l'estomac des animaux."],"pourquoi":"Le laurier fabrique des huiles odorantes pour se défendre. Elles irritent le ventre d'un animal qui en mange. Les feuilles sont coriaces : une feuille entière avalée peut aussi bloquer le tube digestif.","symptomes":["Vomissements","Diarrhée","Mal au ventre ou ventre dur si une feuille bloque l'intestin"],"que_faire":["Ne faites pas vomir votre animal, sauf si un vétérinaire vous le demande.","Appelez tout de suite votre vétérinaire ou un service d'urgence vétérinaire. Dites quelle plante, quelle partie et quelle quantité.","Emportez un morceau de la plante ou une photo.","Si l'animal est très mou, tremble, ne respire pas bien ou perd connaissance : allez en urgence chez le vétérinaire."],"precision":"Le laurier-sauce (Laurus nobilis) est « non toxique » pour la personne mais l'ASPCA le classe toxique pour chats, chiens et chevaux. Attention à la confusion avec le laurier-cerise (Prunus laurocerasus) : feuilles à bord denté, pétiole vert, odeur d'amande ; laurier-sauce : bord un peu ondulé, pétiole rougeâtre, odeur camphrée.","verifie":true,"sources":[{"titre":"ASPCA — Bay Laurel","url":"https://www.aspca.org/pet-care/aspca-poison-control/toxic-and-non-toxic-plants/bay-laurel"},{"titre":"Toxins (MDPI) — Confusion entre laurier-sauce et laurier-cerise","url":"https://mdpi.com/2072-6651/14/11/726"}],"precautions":["Retirez toujours la feuille du plat avant de servir.","Ne confondez pas avec le laurier-cerise (feuilles dentées, odeur d'amande quand on les froisse) : toxique.","Gardez le laurier hors de portée des animaux qui mâchent."]},
 "estragon": {"niveau":"faible","resume":"Peut donner vomissements et diarrhée aux chats et aux chiens. Aromate normal pour les personnes.","animaux":{"chats":"oui","chiens":"oui","autres":"Chevaux : toxique (ASPCA)."},"humains":{"enfants":"non","adultes":"non","texte":"Se mange sans danger comme aromate."},"parties":["Feuilles et tiges"],"substances":["Huiles essentielles : elles irritent l'estomac de l'animal."],"pourquoi":"L'estragon fabrique des huiles aromatiques pour se défendre. Elles irritent le ventre d'un animal qui en mange.","symptomes":["Vomissements légers","Diarrhée"],"que_faire":["Ne faites pas vomir votre animal, sauf si un vétérinaire vous le demande.","Appelez tout de suite votre vétérinaire ou un service d'urgence vétérinaire. Dites quelle plante, quelle partie et quelle quantité.","Emportez un morceau de la plante ou une photo.","Si l'animal est très mou, tremble, ne respire pas bien ou perd connaissance : allez en urgence chez le vétérinaire."],"precision":"L'ASPCA classe l'estragon (Artemisia dracunculus) comme toxique pour chiens, chats et chevaux : cela contredit la fiche actuelle (chatChien = false).","verifie":true,"sources":[{"titre":"ASPCA — Tarragon","url":"https://www.aspca.org/pet-care/aspca-poison-control/toxic-and-non-toxic-plants/tarragon"}],"precautions":["Gardez les plantes hors de portée des jeunes enfants et des animaux.","Apprenez aux enfants à ne rien manger au jardin sans demander à un adulte.","Lavez-vous les mains après avoir jardiné."]},
 "fraisier": {"niveau":"aucune","resume":"Le fraisier n'est pas toxique pour les chats et les chiens (ASPCA). Aucun danger connu pour les personnes en quantité normale.","animaux":{"chats":"non","chiens":"non","autres":"Chevaux : non toxique (ASPCA)."},"humains":{"enfants":"non","adultes":"non","texte":"Les fraises se mangent sans danger. Lavez-les avant."},"parties":["Aucune partie connue comme toxique"],"substances":["Aucune substance dangereuse connue à dose normale."],"pourquoi":"Cette plante n'est pas connue pour être dangereuse. Comme toute plante, trop en manger peut seulement dérégler le ventre d'un animal.","symptomes":["Rien en général","Ventre un peu dérangé si l'animal en mange beaucoup"],"que_faire":["Rien d'urgent en général.","Si l'animal vomit beaucoup ou semble mal : appelez votre vétérinaire."],"precision":"Fiche ASPCA : fraisier (Fragaria).","verifie":true,"sources":[{"titre":"ASPCA — Strawberry","url":"https://www.aspca.org/pet-care/aspca-poison-control/toxic-and-non-toxic-plants/strawberry"}],"precautions":["Gardez les plantes hors de portée des jeunes enfants et des animaux.","Apprenez aux enfants à ne rien manger au jardin sans demander à un adulte.","Lavez-vous les mains après avoir jardiné."]},
 "framboisier": {"niveau":"faible","resume":"Les framboises se mangent. Pour les chiens, de petites quantités sont acceptées. Pour les chats, la confirmation manque.","animaux":{"chats":"inconnu","chiens":"non","autres":""},"humains":{"enfants":"non","adultes":"non","texte":"Les fruits se mangent sans danger. Lavez-les avant."},"parties":["Aucune partie connue comme toxique"],"substances":["Un peu de xylitol naturel dans le fruit, en très petite quantité (dangereux pour les chiens seulement à forte dose)."],"pourquoi":"La plante ne fabrique pas de poison connu. Le fruit contient très peu de xylitol, un sucre dangereux pour le chien en grande quantité (surtout dans les produits sans sucre).","symptomes":["Ventre dérangé en grande quantité"],"que_faire":["Rien d'urgent en petite quantité.","Si le chien a mangé beaucoup de framboises ou un produit « sans sucre » : appelez votre vétérinaire."],"precision":"Pas de fiche ASPCA trouvée pour le framboisier. Rover (blog grand public) : petites quantités acceptables pour les chiens. Rien de confirmé pour les chats ni pour les feuilles.","verifie":false,"sources":[{"titre":"Rover — Can dogs eat raspberries","url":"https://www.rover.com/blog/can-dogs-eat-raspberries"}],"precautions":["Gardez les plantes hors de portée des jeunes enfants et des animaux.","Apprenez aux enfants à ne rien manger au jardin sans demander à un adulte.","Lavez-vous les mains après avoir jardiné."]},
 "myrtillier": {"niveau":"faible","resume":"Les myrtilles se mangent. Pour les chiens, en petite quantité. Pour les chats, la confirmation manque.","animaux":{"chats":"inconnu","chiens":"non","autres":""},"humains":{"enfants":"non","adultes":"non","texte":"Les fruits se mangent sans danger. Lavez-les avant."},"parties":["Aucune partie connue comme toxique"],"substances":["Aucune substance dangereuse connue."],"pourquoi":"La plante n'est pas connue pour fabriquer de poison. Trop de fruits peuvent seulement donner mal au ventre.","symptomes":["Vomissements ou diarrhée en grande quantité","Risque d'étouffement pour un petit chien"],"que_faire":["Rien d'urgent en petite quantité.","Si l'animal vomit beaucoup : appelez votre vétérinaire."],"precision":"Pas de fiche ASPCA trouvée pour le myrtillier. Petsecure : myrtilles acceptables en petite quantité pour les chiens. Rien de confirmé pour les chats ni pour les feuilles.","verifie":false,"sources":[{"titre":"Petsecure — Can dogs eat blueberries","url":"https://petsecure.com/en-CA/blogs/Can-dogs-eat-blueberries"},{"titre":"ASPCA — Foods you can safely share","url":"https://www.aspca.org/news/sharing-caring-foods-you-can-safely-share-your-pet"}],"precautions":["Gardez les plantes hors de portée des jeunes enfants et des animaux.","Apprenez aux enfants à ne rien manger au jardin sans demander à un adulte.","Lavez-vous les mains après avoir jardiné."]},
 "groseillier": {"niveau":"faible","resume":"Le groseillier : pas de toxicité connue, mais non confirmée. Par prudence, ne la laissez pas manger aux animaux. Ne pas confondre avec les raisins secs et les raisins de Corinthe, toxiques pour les chiens.","animaux":{"chats":"inconnu","chiens":"inconnu","autres":""},"humains":{"enfants":"non","adultes":"non","texte":"Les baies se mangent sans danger. Lavez-les avant."},"parties":["Aucune partie connue comme toxique"],"substances":["Aucune substance dangereuse connue."],"pourquoi":"Les groseilliers (Ribes) ne sont pas connus pour fabriquer de poison. Mais les raisins, raisins secs et raisins de Corinthe (Vitis, une autre plante) peuvent abîmer les reins des chiens.","symptomes":["Rien de connu"],"que_faire":["Si votre chien a mangé du raisin, des raisins secs ou de Corinthe : appelez tout de suite votre vétérinaire.","Pour les groseilles et cassis : si l'animal vomit beaucoup, appelez votre vétérinaire."],"precision":"Pas de fiche ASPCA trouvée pour ce Ribes. VCA précise que les raisins, raisins secs et raisins de Corinthe de type Zante (Vitis) sont toxiques pour les chiens, mais que les groseilles de type Ribes ne sont pas décrites comme provoquant des atteintes rénales. Pas de toxicité connue mais non confirmée : par prudence, ne pas la laisser manger.","verifie":false,"sources":[{"titre":"VCA — Grape, raisin and currant poisoning in dogs","url":"https://vcahospitals.com/know-your-pet/grape-raisin-and-currant-poisoning-in-dogs"}],"precautions":["Gardez les plantes hors de portée des jeunes enfants et des animaux.","Apprenez aux enfants à ne rien manger au jardin sans demander à un adulte.","Lavez-vous les mains après avoir jardiné."]},
 "cassissier": {"niveau":"faible","resume":"Le cassissier : pas de toxicité connue, mais non confirmée. Par prudence, ne la laissez pas manger aux animaux. Ne pas confondre avec les raisins secs et les raisins de Corinthe, toxiques pour les chiens.","animaux":{"chats":"inconnu","chiens":"inconnu","autres":""},"humains":{"enfants":"non","adultes":"non","texte":"Les baies se mangent sans danger. Lavez-les avant."},"parties":["Aucune partie connue comme toxique"],"substances":["Aucune substance dangereuse connue."],"pourquoi":"Les groseilliers (Ribes) ne sont pas connus pour fabriquer de poison. Mais les raisins, raisins secs et raisins de Corinthe (Vitis, une autre plante) peuvent abîmer les reins des chiens.","symptomes":["Rien de connu"],"que_faire":["Si votre chien a mangé du raisin, des raisins secs ou de Corinthe : appelez tout de suite votre vétérinaire.","Pour les groseilles et cassis : si l'animal vomit beaucoup, appelez votre vétérinaire."],"precision":"Pas de fiche ASPCA trouvée pour ce Ribes. VCA précise que les raisins, raisins secs et raisins de Corinthe de type Zante (Vitis) sont toxiques pour les chiens, mais que les groseilles de type Ribes ne sont pas décrites comme provoquant des atteintes rénales. Pas de toxicité connue mais non confirmée : par prudence, ne pas la laisser manger.","verifie":false,"sources":[{"titre":"VCA — Grape, raisin and currant poisoning in dogs","url":"https://vcahospitals.com/know-your-pet/grape-raisin-and-currant-poisoning-in-dogs"}],"precautions":["Gardez les plantes hors de portée des jeunes enfants et des animaux.","Apprenez aux enfants à ne rien manger au jardin sans demander à un adulte.","Lavez-vous les mains après avoir jardiné."]},
 "citronnier": {"niveau":"faible","resume":"Le jus et la chair du citron se mangent. Les feuilles, l'écorce et la peau peuvent irriter la peau et le ventre des animaux.","animaux":{"chats":"oui","chiens":"oui","autres":"Chevaux : toxique (ASPCA)."},"humains":{"enfants":"non","adultes":"non","texte":"Le fruit se mange. Les huiles de la peau et des feuilles peuvent irriter la peau, surtout au soleil : lavez-vous les mains après avoir pressé des zestes."},"parties":["Feuilles","Écorce et peau du fruit","Pépins","Plante entière (pour les animaux)"],"substances":["Huiles essentielles (limonène) : irritantes pour le ventre et la peau.","Psoralènes : des substances qui rendent la peau sensible au soleil."],"pourquoi":"Les agrumes fabriquent des huiles piquantes dans leurs feuilles et leur peau pour éloigner les insectes. Elles irritent la bouche et l'estomac des animaux et rendent parfois la peau sensible à la lumière.","symptomes":["Vomissements, diarrhée","Fatigue, abattement","Peau rouge ou irritée (contact et soleil)"],"que_faire":["Ne faites pas vomir votre animal, sauf si un vétérinaire vous le demande.","Appelez tout de suite votre vétérinaire ou un service d'urgence vétérinaire. Dites quelle plante, quelle partie et quelle quantité.","Emportez un morceau de la plante ou une photo.","Si l'animal est très mou, tremble, ne respire pas bien ou perd connaissance : allez en urgence chez le vétérinaire."],"precision":"L'ASPCA liste le citron (Citrus limonia) toxique pour chiens, chats et chevaux. La page « aliments à éviter » dit qu'un peu de chair de fruit n'entraîne en général qu'un petit trouble du ventre.","verifie":true,"sources":[{"titre":"ASPCA — Lemon","url":"https://www.aspca.org/pet-care/aspca-poison-control/toxic-and-non-toxic-plants/lemon"},{"titre":"ASPCA — People foods to avoid feeding your pets","url":"https://www.aspca.org/pet-care/aspca-poison-control/people-foods-avoid-feeding-your-pets"}],"precautions":["Gardez les plantes hors de portée des jeunes enfants et des animaux.","Apprenez aux enfants à ne rien manger au jardin sans demander à un adulte.","Lavez-vous les mains après avoir jardiné."]},
 "figuier": {"niveau":"faible","resume":"La sève blanche du figuier irrite la peau, surtout au soleil. Les figues mûres se mangent. Pour les animaux, la confirmation manque : par prudence, ne pas laisser mâcher la plante.","animaux":{"chats":"inconnu","chiens":"inconnu","autres":""},"humains":{"enfants":"oui","adultes":"oui","texte":"La sève des feuilles et des branches peut donner des rougeurs et des cloques quand la peau touche la sève puis le soleil. Mettez des gants pour tailler. Les figues mûres se mangent, mais la peau autour de la bouche peut parfois réagir."},"parties":["Sève blanche (feuilles, branches, jeunes fruits)","Feuilles"],"substances":["Ficine (enzyme qui irrite) et ficusine, un psoralène : des substances qui rendent la peau sensible au soleil."],"pourquoi":"Le figuier fabrique une sève collante pour se protéger des insectes. Elle contient une enzyme qui irrite et une substance qui réagit au soleil sur la peau.","symptomes":["Peau rouge, qui gratte ou qui brûle","Cloques après exposition au soleil","Taches violettes qui durent (cas rares)","Bouche rouge ou cloques si on en croque"],"que_faire":["Rincez la peau à l'eau et au savon doux tout de suite, évitez le soleil.","Si cloques ou forte douleur : demandez un avis médical.","Pour un animal qui a mâché la plante : appelez votre vétérinaire en cas de bave, vomissements ou irritation."],"precision":"Pour Ficus carica, IVIS écrit qu'un empoisonnement animal est peu probable. L'ASPCA liste « Fig » mais pour Ficus benjamina (figuier d'appartement), toxique : une autre espèce. La fiche actuelle (chatChien = true) est donc à nuancer pour le figuier à fruits.","verifie":false,"sources":[{"titre":"IVIS — Ficus (figuier), guide des plantes toxiques","url":"https://www.ivis.org/library/guide-to-poisonous-house-and-garden-plants/ficus-species-ficus-fig"}],"precautions":["Gants et manches longues pour tailler le figuier, de préférence par temps couvert.","Lavez-vous bien après avoir cueilli.","Ne laissez pas les enfants mâcher les feuilles ou les branches."]},
 "pommier-colonnaire": {"niveau":"moderee","resume":"La pomme se mange. Les pépins, les feuilles et les tiges contiennent un poison à base de cyanure : dangereux pour les chats et les chiens, surtout en grande quantité.","animaux":{"chats":"oui","chiens":"oui","autres":"Chevaux : toxique (ASPCA)."},"humains":{"enfants":"non","adultes":"non","texte":"La chair de la pomme est sans danger. Il vaut mieux ne pas avaler beaucoup de pépins écrasés ni mâcher les feuilles."},"parties":["Pépins","Feuilles (surtout flétries)","Tiges"],"substances":["Glycosides cyanogènes : ils libèrent du cyanure quand la plante est écrasée ou mâchée. Le cyanure empêche le corps d'utiliser l'oxygène."],"pourquoi":"Le pommier protège ses graines avec des glycosides cyanogènes. Si une graine ou une feuille est mâchée, elle libère un peu de cyanure. Quelques pépins entiers avalés ne sont en général pas un souci, mais beaucoup de pépins écrasés, de feuilles ou de tiges peuvent être dangereux pour un animal.","symptomes":["Respiration difficile, halètement","Pupilles dilatées","Gencives rouge vif","Choc, effondrement (cas graves)"],"que_faire":["Ne faites pas vomir votre animal, sauf si un vétérinaire vous le demande.","Appelez tout de suite votre vétérinaire ou un service d'urgence vétérinaire. Dites quelle plante, quelle partie et quelle quantité.","Emportez un morceau de la plante ou une photo.","Si l'animal est très mou, tremble, ne respire pas bien ou perd connaissance : allez en urgence chez le vétérinaire."],"precision":"L'ASPCA liste « Apple » (Malus sylvestris) toxique pour chiens, chats et chevaux, avec cyanure dans tiges, feuilles et pépins. Pour les personnes, le danger des pépins n'a pas été détaillé par une source ouverte ici : la quantité compte, et quelques pépins avalés sont généralement sans conséquence.","verifie":true,"sources":[{"titre":"ASPCA — Apple","url":"https://www.aspca.org/pet-care/aspca-poison-control/toxic-and-non-toxic-plants/apple"}],"precautions":["Retirez le trognon et les pépins avant de donner de la pomme à un animal.","Ne laissez pas les animaux mâcher les feuilles ou les branches de taille.","Ramassez les branches coupées : les feuilles flétries sont plus dangereuses."]}
});})();
